warp:
shader_body
{
vec2 _uv = uv;

    ret.x = texture( sampler_main, (_uv-0.5)*1.00+0.5 ).x;
    ret.y = texture( sampler_main, (_uv-0.5)*0.98+0.5 ).y;
vec4 noise9 = texture(sampler_noisevol_hq, 
                      ((_uv.xyy*q27 )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*q29
                     ).xyz;
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
    ret.z = texture( sampler_main, (_uv-0.5)*0.95+0.5 ).z;

    // .x = fastest layer, .z = slowest
    // slowly shift stuff toward the front, over time:
    ret += vec3(-ret.x,ret.x-ret.y,ret.y-ret.z)*0.03, (bass_att-1.0)*0.1;

    // ERROR DIFFUSION DITHER - looks great
    vec2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw + rand_frame.xy;
    ret += (texture(sampler_noise_lq, dither_uv).xyz-0.5)/256.0*3.0;

    // darken over time
//    ret -= 0.003;
    //ret *= 0.99;
    //ret *= 0.97*clamp( length(_uv - uv_orig)*200.0 , 0.0, 1.0);  // center only
ret = ret * (0.95 + (sin(mid)*0.05));

}

comp:
shader_body
{

    vec2 uv_echo = (uv - 0.5)*1.000*vec2(-1.0,-1.0) + 0.5;
    ret = mix( texture(sampler_main, uv).xyz, 
                texture(sampler_main, uv_echo).xyz, 
                0.50 
              ); //video echo
    ret *= 2.00; //gamma
    vec3 retish = vec3(1.0 - ret*(1.0-ret)*4.0); //solarize
    ret = ((texture(sampler_blur3, uv).xyz * scale3) + bias3)*2.0 + ((texture(sampler_blur3, uv_echo).xyz * scale3) + bias3)*2.0 + ret;
}
